10	/** Verifies :has() relative-selector anchoring, nesting, error, and re-evaluation semantics. */
11	public class HasRelativeSelectorTest {
12	
13	    @Test void nestedHasKeepsAnchorPerLayer() {
14	        Document doc = Jsoup.parse(
15	            "<section id=s1><article><h2>in</h2></article></section>" + // article contains h2, not adjacent
16	            "<section id=s2><article></article><h2>adj</h2></section>" + // article immediately followed by h2
17	            "<section id=s3><article></article><p></p><h2>late</h2></section>"); // h2 not immediate
18	        Elements found = doc.select("section:has(article:has(+ h2))");
19	        assertEquals(1, found.size());
20	        assertEquals("s2", found.get(0).id());
21	    }
22	
23	    @Test void innerHasDoesNotDriftToOuterSiblings() {
24	        // section s1's article has no adjacent h2, but the section itself is followed by h2 - must not match
25	        Document doc = Jsoup.parse(
26	            "<div><section id=s1><article></article></section><h2>x</h2></div>");
27	        assertEquals(0, doc.select("section:has(article:has(+ h2))").size());
28	    }
29	
30	    @Test void leadingCombinators() {
31	        Document doc = Jsoup.parse(
32	            "<div id=d1><p></p><span></span></div>" +
33	            "<div id=d2><p></p></div>" +
34	            "<div id=d3><em><p></p></em></div>");
35	        assertEquals("d1 d2 d3", ids(doc.select("div:has(p)")));
36	        assertEquals("d1 d2", ids(doc.select("div:has(> p)")));
37	        assertEquals("d1 d2", ids(doc.select("div:has(+ div p)"))); // immediate next sibling div contains p
38	        assertEquals("d1 d2", ids(doc.select("div:has(~ div)")));
39	    }
