42	        Document doc = Jsoup.parse("<div><p id=a></p><em></em><h2></h2></div><div><p id=b></p><h2></h2></div>");
43	        Elements found = doc.select("p:has(+ h2)");
44	        assertEquals(1, found.size());
45	        assertEquals("b", found.get(0).id());
46	    }
