    public Is(Evaluator evaluator) {
        super(evaluator);
    }

    @Override
    boolean evaluateMatch(Element root, Node node) {
        return evaluator.matches(root, node);
    }

    @Override protected int cost() {
        return 2 + evaluator.cost();
    }

